import React, { useState, useRef, useCallback, useEffect } from 'react';
import Webcam from 'react-webcam';
import { attendanceAPI } from '../api_service';
import { 
  CheckCircle, 
  XCircle, 
  RefreshCw, 
  UserCheck, 
  ShieldAlert,
  Fingerprint
} from 'lucide-react';

const CameraRecognition = () => {
  const webcamRef = useRef(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const [autoMode, setAutoMode] = useState(false);

  const videoConstraints = {
    width: 1280,
    height: 720,
    facingMode: "user"
  };

  /**
   * ✅ NETTOYAGE DU FLUX CAMÉRA
   * Stoppe la caméra quand l'utilisateur quitte le composant
   */
  useEffect(() => {
    return () => {
      if (webcamRef.current && webcamRef.current.stream) {
        const tracks = webcamRef.current.stream.getTracks();
        tracks.forEach(track => {
          track.stop();
          console.log(`📹 [CLEANUP] Track ${track.kind} arrêté`);
        });
      }
    };
  }, []);

  /**
   * 🚀 RECONNAISSANCE FACIALE
   */
  const handleCapture = useCallback(async () => {
    if (!webcamRef.current) return;

    setLoading(true);
    setError(null);

    try {
      const imageSrc = webcamRef.current.getScreenshot();
      if (!imageSrc) throw new Error("Capture impossible");

      const response = await attendanceAPI.recognize(imageSrc);
      const data = response.data;

      if (data.success) {
        // ✅ AJOUT DE ATTENDANCE_ID
        setResult({
          name: data.student,
          email: data.email,
          confidence: data.confidence,
          timestamp: data.timestamp,
          message: data.message,
          attendanceId: data.attendance_id // Stockage de l'ID pour référence
        });
      }
    } catch (err) {
      console.error("❌ Erreur API:", err);

      // ✅ GESTION DES ERREURS UNIFORMISÉE (Priorité à .error)
      const backendError = 
        err.response?.data?.error || 
        err.response?.data?.message || 
        "Une erreur est survenue lors de l'identification";

      setError(backendError);
      setResult(null);
    } finally {
      setLoading(false);
    }
  }, [webcamRef]);

  // Mode Automatique
  useEffect(() => {
    let interval;
    if (autoMode) {
      interval = setInterval(() => {
        if (!loading) handleCapture();
      }, 5000);
    }
    return () => clearInterval(interval);
  }, [autoMode, loading, handleCapture]);

  return (
    <div className="flex flex-col items-center p-6 space-y-6 bg-gray-50 min-h-screen">
      <div className="text-center">
        <h1 className="text-3xl font-bold text-blue-900 flex items-center justify-center gap-2">
          <UserCheck size={32} /> Pointage Biométrique
        </h1>
        <p className="text-gray-500 mt-2">Placez votre visage au centre de la caméra</p>
      </div>

      <div className="relative">
        <div className="overflow-hidden rounded-3xl border-8 border-white shadow-2xl bg-black">
          <Webcam
            audio={false}
            ref={webcamRef}
            screenshotFormat="image/jpeg"
            videoConstraints={videoConstraints}
            className="w-[640px] h-[360px] object-cover"
          />
          {loading && (
            <div className="absolute inset-0 flex items-center justify-center bg-blue-900/10 backdrop-blur-sm">
              <RefreshCw className="text-white animate-spin" size={48} />
            </div>
          )}
        </div>

        <div className="flex justify-center gap-4 mt-8">
          <button
            onClick={handleCapture}
            disabled={loading}
            className={`px-10 py-4 rounded-2xl font-bold text-white transition-all transform active:scale-95 flex items-center gap-2 shadow-lg ${
              loading ? 'bg-gray-400 cursor-not-allowed' : 'bg-blue-600 hover:bg-blue-700'
            }`}
          >
            <Fingerprint size={20} />
            {loading ? 'Analyse...' : 'Scanner mon visage'}
          </button>

          <button
            onClick={() => setAutoMode(!autoMode)}
            className={`px-6 py-4 rounded-2xl font-bold border-2 transition-all ${
              autoMode 
                ? 'bg-green-100 border-green-500 text-green-700' 
                : 'bg-white border-gray-300 text-gray-500 hover:bg-gray-100'
            }`}
          >
            {autoMode ? 'Auto-Scan: ON' : 'Auto-Scan: OFF'}
          </button>
        </div>
      </div>

      <div className="w-full max-w-xl">
        {result && (
          <div className="bg-white border-l-8 border-green-500 p-6 rounded-2xl shadow-xl animate-in fade-in slide-in-from-top-2">
            <div className="flex items-start gap-5">
              <div className="bg-green-100 p-3 rounded-full">
                <CheckCircle className="text-green-600" size={32} />
              </div>
              <div className="flex-1">
                <h2 className="text-2xl font-black text-gray-800">{result.name}</h2>
                <p className="text-gray-500 font-medium">{result.email}</p>
                <div className="mt-4 grid grid-cols-2 gap-4 border-t pt-4">
                  <div>
                    <span className="text-[10px] uppercase text-gray-400 font-bold block">Ref Pointage</span>
                    <span className="font-mono text-blue-600 text-sm">#{result.attendanceId || 'N/A'}</span>
                  </div>
                  <div className="text-right">
                    <span className="text-[10px] uppercase text-gray-400 font-bold block">Score IA</span>
                    <span className="font-bold text-gray-700">{(result.confidence * 100).toFixed(1)}%</span>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {error && (
          <div className="bg-red-50 border-l-8 border-red-500 p-6 rounded-2xl shadow-lg flex items-center gap-4">
            <XCircle className="text-red-600 shrink-0" size={32} />
            <div>
              <h3 className="font-bold text-red-900">Échec de l'identification</h3>
              <p className="text-red-700 text-sm">{error}</p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default CameraRecognition;
